import shutil
import openpyxl
from openpyxl.utils import column_index_from_string, get_column_letter
from datetime import datetime, date

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

DEST = "b2b, sez, de"
SRC = "cdnr"

if DEST not in wb.sheetnames:
    ws = wb.create_sheet(DEST)
else:
    ws = wb[DEST]

vdest = vals[DEST]
vsrc = vals[SRC] if SRC in vals.sheetnames else None

COLS = [get_column_letter(i) for i in range(1, 23)]
IDX = {c: column_index_from_string(c) for c in COLS}

def empty(v):
    return v is None or (isinstance(v, str) and v.strip() == "")

def clean(v):
    if isinstance(v, str):
        s = v.strip()
        return s if s else None
    return v

def to_date(v):
    if v is None or isinstance(v, bool):
        return v
    if isinstance(v, datetime):
        return v
    if isinstance(v, date):
        return datetime(v.year, v.month, v.day)
    if isinstance(v, (int, float)):
        if 1 <= v <= 200000:
            try:
                return openpyxl.utils.datetime.from_excel(v)
            except Exception:
                return v
        return v
    if isinstance(v, str):
        s = v.strip()
        if not s:
            return None
        for fmt in ("%d-%b-%Y", "%d-%B-%Y", "%d-%m-%Y", "%Y-%m-%d",
                    "%d/%m/%Y", "%m/%d/%Y", "%Y/%m/%d", "%d-%b-%y", "%d-%B-%y"):
            try:
                return datetime.strptime(s, fmt)
            except Exception:
                pass
        try:
            f = float(s)
            if 1 <= f <= 200000:
                return openpyxl.utils.datetime.from_excel(f)
        except Exception:
            pass
        return s
    return v

def negate(v):
    if v is None or isinstance(v, bool):
        return v
    if isinstance(v, (int, float)):
        return -v
    if isinstance(v, str):
        s = v.strip()
        if not s:
            return None
        try:
            return -float(s)
        except Exception:
            return s
    return v

def headers(sheet):
    h = {}
    for c in COLS:
        v = sheet.cell(row=4, column=IDX[c]).value
        if v is not None:
            h[c] = str(v).strip()
    return h

def generic(h):
    return bool(h) and all(h.get(c) == c for c in COLS if c in h)

